**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <map>
using namespace std;

int main() {
    ifstream fA("lista_A.txt"), fB("lista_B.txt");
    vector<int> A, B;
    int x;
    while (fA >> x) A.push_back(x);
    while (fB >> x) B.push_back(x);

    map<int, int> pozB;
    for (int i = 0; i < (int)B.size(); i++) {
        pozB[B[i]] = i + 1;
    }

    vector<int> wspolne;
    for (int i = 0; i < (int)A.size(); i++) {
        if (pozB.count(A[i])) {
            wspolne.push_back(i);
        }
    }

    cout << "a) Elementy wspolne:" << endl;

    cout << endl << "b) Pozycje wspolnych elementow:" << endl;
    for (int i : wspolne) {
        cout << "   " << A[i] << ": lista_A[" << i + 1 << "], lista_B[" << pozB[A[i]] << "]" << endl;
    }
    return 0;
}
```

Weryfikacja:
- lista_A: 12(1), 7(2), 25(3), 3(4), 18(5), 9(6)
- lista_B: 5(1), 18(2), 3(3), 30(4), 7(5), 11(6), 25(7)
- pozB: {5:1, 18:2, 3:3, 30:4, 7:5, 11:6, 25:7}
- Iteracja po A:
  - 12: brak w B
  - 7: jest w B na poz 5 -> wspolny
  - 25: jest w B na poz 7 -> wspolny
  - 3: jest w B na poz 3 -> wspolny
  - 18: jest w B na poz 2 -> wspolny
  - 9: brak w B
- Wynik: 7(A[2],B[5]), 25(A[3],B[7]), 3(A[4],B[3]), 18(A[5],B[2])
